const out = [];

for (const item of items) {
  const r = item.json;
  const task = String(r.Au_TaskName || '').trim();
  const description = String(r.Au_Description || '');

  let changeType = 'UNKNOWN';

  if (['MetaEntry','Meta Entry','MetaData Entry'].includes(task)) changeType = 'NEW';
  else if (['MetaEdit','Meta Edit','MetaData Edit'].includes(task)) changeType = 'MODIFIED';
  else if (task === 'Meta Delete') changeType = 'DELETED';

  const match = description.match(/\bNITL-[A-Za-z0-9-]+\b/i);
  const assetId = match ? match[0].toUpperCase() : null;

  if (!assetId || changeType === 'UNKNOWN') continue;

  out.push({json: {
    audit_id: Number(r.Au_id),
    change_date: r.Au_ActionDate,
    change_month: r.Au_ActionDate ? new Date(r.Au_ActionDate).toLocaleString('en-US', {month:'long', year:'numeric'}) : '',
    asset_id: assetId,
    change_type: changeType,
    user_id: r.Au_UserID ?? null,
    username: r.u_name ?? '',
    login_id: r.u_loginid ?? '',
    email: r.u_email ?? '',
    task_name: task,
    description,
    category: r.Au_Category ?? ''
  }});
}

return out;

