UPDATE n8n_workflow_state
SET last_audit_id = {{
  Math.max(
    ...$('Get New Asset Audit Events')
      .all()
      .map(item => Number(item.json.Au_id))
      .filter(id => Number.isFinite(id))
  )
}}
WHERE workflow_name = 'ITAMS_ASSET_CHANGE_TRACKER';
